e","recipe_id":"rcp_mem_astral_rupture","tier":3,"min_learner_level":60,"weapon_family":"Orb","max_level":10,"scalable_special_effects":[],"learning_quest_template":"learning","training_quest_template":"training"}],"npc":{"npc_id":"npc_skill_artisan_ivara","name":"Ivara","title":"Skill Artisan","role":"CRAFTER","faction":"NEUTRAL","dialogue_tree":"dialog_skill_artisan_ivara","location":"Central Spire Bazaar","region_id":"CENTRAL_SPIRE_BAZAAR","description":"A memory engraver who turns combat echoes into transferable skill memories.","actions":["open_crafting"],"available_services":["CRAFT"],"greeting":"A memory is a beginning, not mastery. What will you make your own?"},"dialogue":{"dialog_id":"dialog_skill_artisan_ivara","npc_id":"npc_skill_artisan_ivara","start_node":"greet","nodes":[{"id":"greet","text":"A memory is a beginning, not mastery. What will you make your own?","options":[{"text":"Craft a Skill Memory.","next":"craft","action":"open_crafting"},{"text":"How do I learn a memory?","next":"learn"},{"text":"How many can I equip?","next":"slots"},{"text":"Tell me about mastery training.","next":"train"},{"text":"Check my training progress.","next":"progress"},{"text":"Can I sell a memory?","next":"trade"},{"text":"Leave.","next":"exit","action":"exit"}]},{"id":"craft","text":"Bring memory chips, a stabilizer, and the essence of the technique. Stronger inscriptions need rarer materials and a larger engraving fee.","options":[{"text":"Back.","next":"greet"}]},{"id":"learn","text":"Choose yourself or a companion before using the memory. It is consumed to begin that learner's quest. Win real battles with the required weapon, then return to an artisan. Only completion unlocks the skill at level one.","options":[{"text":"Back.","next":"greet"}]},{"id":"slots","text":"Each learner has two memory slots, separate from class techniques. Certain passives may add slots. You may learn many memories and change your selection outside battle. An incompatible weapon disables its technique.","options":[{"text":"Back.","next":"greet"}]},{"id":"train","text":"Mastery grows from level one to ten. Each new level needs its own training quest: meaningful uses, worthy victories, and an artisan's review. Your current mastery remains usable while training.","options":[{"text":"Back.","next":"greet"}]},{"id":"progress","text":"Learning and training records belong to the chosen learner. Paused lessons can resume; they do not return the consumed memory. Your quest journal will track the objectives once lessons are available.","options":[{"text":"Back.","next":"greet"}]},{"id":"trade","text":"An unused inscription is unbound and may be sold on the market. Once used, the lesson and all mastery belong to that learner. They cannot be transferred or sold.","options":[{"text":"Back.","next":"greet"}]},{"id":"exit","text":"Keep your hands steady and your memories sharper.","options":[]}]},"contract":{"schema_version":1,"status":"runtime_ready_client_release_required","source_type":"Skill_Memory","item_type":"SKILL_MEMORY","base_slots_per_learner":2,"max_skill_level":10,"weapon_families":["Knuckle","Sword","Dagger","Spear","Polearm","Staff","Orb","Grimoire","Shield"],"weapon_matching":"explicit_equipped_item_type_suffix_after_WEAPON_prefix_in_either_hand","equipment_type_format":{"weapon":"WEAPON_{SUBTYPE}","accessory":"ACCESSORY_{SUBTYPE}"},"weapon_subtype_comparison":"uppercase_exact_match; no implicit aliases","slot_bonus_effect":"increase_skill_memory_slots","slot_bonus_sources":["class_passive","race_passive","ally_passive","equipped_item_passive"],"memory_skills_can_grant_slots":false,"learner_key":["player_id","learner_type","learner_id"],"client_storage_keys":{"learned":"skill_memory_levels","equipped":"equipped_memory_skill_ids","learning":"quest_progress.definition_snapshot.skill_memory"},"persistent_state":{"learned_memories":"map skill_id -> level (1..10)","equipped_memories":"ordered unique skill_ids, separate from class skills","learning_attempts":"map skill_id -> quest_id, attempt_id, status, objective_progress","training_attempts":"map skill_id -> from_level, to_level, quest_id, attempt_id, objective_progress"},"states":["unlearned","learning","learned","training"],"item_use":{"transaction":["validate_selected_owned_learner","reject_known_or_pending_skill","check_min_level","consume_exactly_one_item","create_learning_quest"],"atomic":true,"idempotency_key":"item_use_request_id","quest_failure_rolls_back_consumption":true,"abandon_policy":"pause_and_resume_same_attempt_without_refund","quest_completion":"unlock_level_1_for_bound_learner_only","weapon_required_at_use":false},"battle_rules":{"resolve":"class_skills_plus_valid_equipped_memories_only","enforce_weapon":"at_equip_and_each_cast","weapon_swap":"keep_loadout_but_disable_incompatible_memory","loadout_changes":"out_of_combat_only","party_rules":"same_contract_independent_progress_per_member"},"progression":{"level_potency_multipliers":[1.0,1.06,1.12,1.18,1.24,1.3,1.36,1.42,1.48,1.54],"scale_only":["damage_formula_result","periodic_effects.percent_atk.value","periodic_effects.heal_over_time.value","healing_amount","shield_amount"],"never_scale":["mp_cost","cooldown_seconds","duration_turns","chance","hit_count","lifesteal_percent","defense_penetration_percent","stat_modifiers","slot_count"],"learning_template":{"id_pattern":"q_mem_learn_{skill_slug}","objectives":["qualifying_victories_with_required_weapon","artisan_turn_in"],"victories_by_tier":[3,5,8]},"training_template":{"id_pattern":"q_mem_train_{skill_slug}_{to_level}","objectives":["meaningful_skill_uses","qualifying_victories","artisan_turn_in"],"uses_formula":"5 * to_level * tier","victories_formula":"to_level + tier"},"event_identity":["battle_id","action_id","learner_id","skill_id","attempt_id"],"eligibility":"living_actor; non_dummy_non_pvp_enemy; enemy_level >= learner_level - 10","meaningful_use":"positive_damage_or_effective_heal_or_absorbed_shield_or_new_status","deduplicate":"one_use_per_action; one_victory_per_battle; never_reward_replayed_events","training_preserves_current_level":true,"quests_authored_in":["P2_learning","P4_training"]},"market":{"unused_item_tradable":true,"bind_on_use":true,"learned_skill_and_progress_tradable":false,"crafted_item_stack_size":20},"activation_requires":["transactional_learning_handler","quest_templates","memory_loadout_resolver","weapon_family_tags","level_scaling"]}}$memory_seed$::jsonb);
create temporary table memory_before_items on commit drop as select id, to_jsonb(t) - 'updated_at' as row_data from public.items t where id not in ('mem_dummy_skill', 'mem_dark_punch', 'mem_iron_jab', 'mem_crescent_slash', 'mem_needle_fang', 'mem_piercing_thrust', 'mem_spark_bolt', 'mem_shield_pulse', 'mem_phantom_step', 'mem_ember_knuckle', 'mem_frost_lance', 'mem_thunder_arc', 'mem_siphon_touch', 'mem_guardian_script', 'mem_venom_edge', 'mem_gravity_break', 'mem_moon_sever', 'mem_chain_impale', 'mem_echo_mend', 'mem_null_ward', 'mem_astral_rupture', 'memory_artisan_knuckle', 'memory_artisan_orb', 'memory_artisan_grimoire', 'memory_artisan_polearm', 'memory_artisan_shield');
insert into public.items as t ("id", "name", "type", "rarity", "level_requirement", "buy_price", "sell_price", "max_stack", "icon_image", "description", "equipment_slots", "stats_bonus", "special_effects") select "id", "name", "type", "rarity", "level_requirement", "buy_price", "sell_price", "max_stack", "icon_image", "description", "equipment_slots", "stats_bonus", "special_effects" from jsonb_populate_recordset(null::public.items, (select (payload->'items') || coalesce(payload->'training_equipment', '[]'::jsonb) from memory_seed_pack)) on conflict (id) do update set "name" = excluded."name", "type" = excluded."type", "rarity" = excluded."rarity", "level_requirement" = excluded."level_requirement", "buy_price" = excluded."buy_price", "sell_price" = excluded."sell_price", "max_stack" = excluded."max_stack", "icon_image" = excluded."icon_image", "description" = excluded."description", "equipment_slots" = excluded."equipment_slots", "stats_bonus" = excluded."stats_bonus", "special_effects" = excluded."special_effects" where row(t."id", t."name", t."type", t."rarity", t."level_requirement", t."buy_price", t."sell_price", t."max_stack", t."icon_image", t."description", t."equipment_slots", t."stats_bonus", t."special_effects") is distinct from row(excluded."id", excluded."name", excluded."type", excluded."rarity", excluded."level_requirement", excluded."buy_price", excluded."sell_price", excluded."max_stack", excluded."icon_image", excluded."description", excluded."equipment_slots", excluded."stats_bonus", excluded."special_effects");
do $verify$ begin if exists (select 1 from memory_before_items b full join (select id, to_jsonb(t) - 'updated_at' as row_data from public.items t where id not in ('mem_dummy_skill', 'mem_dark_punch', 'mem_iron_jab', 'mem_crescent_slash', 'mem_needle_fang', 'mem_piercing_thrust', 'mem_spark_bolt', 'mem_shield_pulse', 'mem_phantom_step', 'mem_ember_knuckle', 'mem_frost_lance', 'mem_thunder_arc', 'mem_siphon_touch', 'mem_guardian_script', 'mem_venom_edge', 'mem_gravity_break', 'mem_moon_sever', 'mem_chain_impale', 'mem_echo_mend', 'mem_null_ward', 'mem_astral_rupture', 'memory_artisan_knuckle', 'memory_artisan_orb', 'memory_artisan_grimoire', 'memory_artisan_polearm', 'memory_artisan_shield')) a using (id) where b.row_data is distinct from a.row_data) then raise exception 'Unrelated items changed'; end if; end $verify$;
create temporary table memory_before_skills on commit drop as select id, to_jsonb(t) - 'updated_at' as row_data from public.skills t where id not in ('sk_mem_dummy_skill', 'sk_mem_dark_punch', 'sk_mem_iron_jab', 'sk_mem_crescent_slash', 'sk_mem_needle_fang', 'sk_mem_piercing_thrust', 'sk_mem_spark_bolt', 'sk_mem_shield_pulse', 'sk_mem_phantom_step', 'sk_mem_ember_knuckle', 'sk_mem_frost_lance', 'sk_mem_thunder_arc', 'sk_mem_siphon_touch', 'sk_mem_guardian_script', 'sk_mem_venom_edge', 'sk_mem_gravity_break', 'sk_mem_moon_sever', 'sk_mem_chain_impale', 'sk_mem_echo_mend', 'sk_mem_null_ward', 'sk_mem_astral_rupture');
insert into public.skills as t ("id", "name", "type", "source_type", "mp_cost", "damage_formula", "effect", "skill_description", "skill_shape", "range", "aoe_radius", "projectile_speed", "cooldown_seconds", "target_attack", "target_effect", "stat_modifiers", "periodic_effects", "control_effects", "special_effects", "usage_requirements", "skill_memory_tier") select "id", "name", "type", "source_type", "mp_cost", "damage_formula", "effect", "skill_description", "skill_shape", "range", "aoe_radius", "projectile_speed", "cooldown_seconds", "target_attack", "target_effect", "stat_modifiers", "periodic_effects", "control_effects", "special_effects", "usage_requirements", "skill_memory_tier" from jsonb_populate_recordset(null::public.skills, (select payload->'skills' from memory_seed_pack)) on conflict (id) do update set "name" = excluded."name", "type" = excluded."type", "source_type" = excluded."source_type", "mp_cost" = excluded."mp_cost", "damage_formula" = excluded."damage_formula", "effect" = excluded."effect", "skill_description" = excluded."skill_description", "skill_shape" = excluded."skill_shape", "range" = excluded."range", "aoe_radius" = excluded."aoe_radius", "projectile_speed" = excluded."projectile_speed", "cooldown_seconds" = excluded."cooldown_seconds", "target_attack" = excluded."target_attack", "target_effect" = excluded."target_effect", "stat_modifiers" = excluded."stat_modifiers", "periodic_effects" = excluded."periodic_effects", "control_effects" = excluded."control_effects", "special_effects" = excluded."special_effects", "usage_requirements" = excluded."usage_requirements", "skill_memory_tier" = excluded."skill_memory_tier" where row(t."id", t."name", t."type", t."source_type", t."mp_cost", t."damage_formula", t."effect", t."skill_description", t."skill_shape", t."range", t."aoe_radius", t."projectile_speed", t."cooldown_seconds", t."target_attack", t."target_effect", t."stat_modifiers", t."periodic_effects", t."control_effects", t."special_effects", t."usage_requirements", t."skill_memory_tier") is distinct from row(excluded."id", excluded."name", excluded."type", excluded."source_type", excluded."mp_cost", excluded."damage_formula", excluded."effect", excluded."skill_description", excluded."skill_shape", excluded."range", excluded."aoe_radius", excluded."projectile_speed", excluded."cooldown_seconds", excluded."target_attack", excluded."target_effect", excluded."stat_modifiers", excluded."periodic_effects", excluded."control_effects", excluded."special_effects", excluded."usage_requirements", excluded."skill_memory_tier");
do $verify$ begin if exists (select 1 from memory_before_skills b full join (select id, to_jsonb(t) - 'updated_at' as row_data from public.skills t where id not in ('sk_mem_dummy_skill', 'sk_mem_dark_punch', 'sk_mem_iron_jab', 'sk_mem_crescent_slash', 'sk_mem_needle_fang', 'sk_mem_piercing_thrust', 'sk_mem_spark_bolt', 'sk_mem_shield_pulse', 'sk_mem_phantom_step', 'sk_mem_ember_knuckle', 'sk_mem_frost_lance', 'sk_mem_thunder_arc', 'sk_mem_siphon_touch', 'sk_mem_guardian_script', 'sk_mem_venom_edge', 'sk_mem_gravity_break', 'sk_mem_moon_sever', 'sk_mem_chain_impale', 'sk_mem_echo_mend', 'sk_mem_null_ward', 'sk_mem_astral_rupture')) a using (id) where b.row_data is distinct from a.row_data) then raise exception 'Unrelated skills changed'; end if; end $verify$;
create temporary table memory_before_npcs on commit drop as select npc_id, to_jsonb(t) - 'updated_at' as row_data from public.npcs t where npc_id not in ('npc_skill_artisan_ivara');
insert into public.npcs as t ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "greeting", "dialogue_tree", "available_services", "actions") select "npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "greeting", "dialogue_tree", "available_services", "actions" from jsonb_populate_recordset(null::public.npcs, (select jsonb_build_array(payload->'npc') from memory_seed_pack)) on conflict (npc_id) do update set "name" = excluded."name", "title" = excluded."title", "role" = excluded."role", "faction" = excluded."faction", "location" = excluded."location", "region_id" = excluded."region_id", "description" = excluded."description", "greeting" = excluded."greeting", "dialogue_tree" = excluded."dialogue_tree", "available_services" = excluded."available_services", "actions" = excluded."actions" where row(t."npc_id", t."name", t."title", t."role", t."faction", t."location", t."region_id", t."description", t."greeting", t."dialogue_tree", t."available_services", t."actions") is distinct from row(excluded."npc_id", excluded."name", excluded."title", excluded."role", excluded."faction", excluded."location", excluded."region_id", excluded."description", excluded."greeting", excluded."dialogue_tree", excluded."available_services", excluded."actions");
do $verify$ begin if exists (select 1 from memory_before_npcs b full join (select npc_id, to_jsonb(t) - 'updated_at' as row_data from public.npcs t where npc_id not in ('npc_skill_artisan_ivara')) a using (npc_id) where b.row_data is distinct from a.row_data) then raise exception 'Unrelated npcs changed'; end if; end $verify$;
create temporary table memory_before_dialogs on commit drop as select dialog_id, to_jsonb(t) - 'updated_at' as row_data from public.dialogs t where dialog_id not in ('dialog_skill_artisan_ivara');
insert into public.dialogs as t ("dialog_id", "npc_id", "start_node", "nodes") select "dialog_id", "npc_id", "start_node", "nodes" from jsonb_populate_recordset(null::public.dialogs, (select jsonb_build_array(payload->'dialogue') from memory_seed_pack)) on conflict (dialog_id) do update set "npc_id" = excluded."npc_id", "start_node" = excluded."start_node", "nodes" = excluded."nodes" where row(t."dialog_id", t."npc_id", t."start_node", t."nodes") is distinct from row(excluded."dialog_id", excluded."npc_id", excluded."start_node", excluded."nodes");
do $verify$ begin if exists (select 1 from memory_before_dialogs b full join (select dialog_id, to_jsonb(t) - 'updated_at' as row_data from public.dialogs t where dialog_id not in ('dialog_skill_artisan_ivara')) a using (dialog_id) where b.row_data is distinct from a.row_data) then raise exception 'Unrelated dialogs changed'; end if; end $verify$;
insert into public.skill_memory_catalog as c(id, schema_version, runtime_ready, payload) select 'v1', 1, (payload->>'runtime_ready')::boolean, payload from memory_seed_pack on conflict (id) do update set schema_version=excluded.schema_version, runtime_ready=excluded.runtime_ready, payload=excluded.payload where c.payload is distinct from excluded.payload or c.runtime_ready is distinct from excluded.runtime_ready;
commit;
